try {
    if (!row) {
        $ctrl.displayEventLogInfo = false;
        $ctrl.eventLogInfo = {};
        return;
    }

    $ctrl.displayEventLogInfo = true;
    $ctrl.eventLogInfo = {};

    const stateObj = row?.raw;
    if (!stateObj || !stateObj.trackerDocumentStateContent) {
        return;
    }

    const contentData = stateObj.trackerDocumentStateContent;
    let rawPayload = null;

    if (contentData.modelContent && contentData.modelContent.content) {
        rawPayload = contentData.modelContent.content;
    } 
    else if (contentData.content) {
        try {
            const decoded = atob(contentData.content);
            const parsed = JSON.parse(decoded);
            rawPayload = parsed.content || parsed;
        } catch (e) {
            rawPayload = contentData.content;
        }
    } 
    else if (contentData.stringContent) {
        rawPayload = contentData.stringContent;
    }

    if (rawPayload) {
        $ctrl.eventLogInfo = $ctrl.utilityService.formatEntityForDisplay(rawPayload);
    }

} catch (e) {
    console.error("Error setting selected event details.", e);
    $ctrl.eventLogInfo = {};
}
